1	// Kiểm tra chế độ lái xe ô tô VinFast VF 3 trên máy tính (docs/superpowers/plans/2026-11-12-lai-xe-oto.md, Task 12; D-034).
2	//   Trang A `?explore=drive` (lái một mình, không máy chủ), mọi bước mô phỏng chạy trong MỘT lần evaluate (không có khung hình xen vào) bằng `__app.drive.step(0.1, input)`:
3	//   Mục 1: vào bằng ?explore=drive (body.explore + body.drive, cam.mode 'car', xe ở drSpawnPose, hướng Đông); trang B `?chooser` bấm thẻ Ô tô (khóa exCar) cũng vào được.
4	//   Mục 2: lái thẳng suốt từng trục (Cầu Rồng, Cầu sông Hàn, Trần Thị Lý, Hầm, Thuận Phước; hai chiều; xe tự động tạm ẩn): mỗi 0,5 s mô phỏng
5	//          |y − mặt đường tại chỗ| ≤ 0,05, đủ 9 điểm mẫu có mặt đường cùng tầng, tâm + bốn góc không nằm trong hộp bao nhà nào (oracle độc lập: ma trận instance
6	//          của cảnh, gồm nhà Thuận Phước); vài điểm đối chiếu thêm bằng tia thẳng xuống vào lưới thật của cảnh. Lái theo điểm qua một chỗ rẽ nút giao đường dọc Đông.
7	//   Mục 3: đâm 100 km/h vào lan can Cầu Rồng, tường hầm, thân rồng: xe dừng phía trong mép ô đường, không xuyên.
8	//   Mục 4: Bạch Đằng về phía Nam từ z = −200 bị chặn trước dốc cầu (gầm đóng); đi vòng bằng nhánh rẽ qua z = 0 sang được z > 60.
9	//   Mục 5: Cầu sông Hàn: ép cầu rời CLOSED (ctrl.state), xe trên nhịp quay được đưa ra ngoài barie trong < 1 s mô phỏng ở tốc độ quay 30×; lái vào barie bị chặn.
10	//   Mục 6: trong hầm: ảnh không có điểm ảnh màu nước ở nửa trên khung; ghi số lệnh vẽ.
11	//   Mục 7: đèn: ban đêm đèn pha / đèn hậu phát sáng, ban ngày bằng 0; phanh thì đèn hậu sáng cả ban ngày (đọc vật liệu của xe thật trong cảnh).
12	//   Mục 9: HUD: số km/h khớp |v| · 3,6; bản đồ nhỏ vẽ được (nhiều màu, có ô hầm); 9 ngôn ngữ đổi chữ HUD; ar không lật (#drHud direction ltr).
13	//   Mục 8 (trang C, D): chặn **/car/vf3.glb: vẫn lái được bằng hình tạm, không lỗi console; giữ 12 s: hình tạm rồi đổi sang xe thật, không nhảy vị trí.
14	//   Mục 10 + 11 (trang F `?test` thường): lệnh vẽ góc mặc định (overview, ban ngày) so với số của `main` trong tests/KET-QUA.md; vào lái một mình tăng ≤ 6;
15	//          rồi thoát lái (drive.stop) và vào Đi dạo: không còn #drHud, ngưỡng ẩn Hầm về cũ, đi dạo chạy bình thường.
16	//   Mục 12: ảnh xem tay tests/screens/drive-check-*.png (bỏ bằng --no-shots).
17	//
18	//   Mỗi mục bọc try / catch riêng (một mục hỏng không làm sập các mục sau), có giới hạn thời gian từng mục và tổng; luôn đóng trình duyệt ở finally.
19	//   npm run build && npm run test:drive [-- --no-shots]
20	import { fileURLToPath } from 'node:url';
21	import { readFileSync, mkdirSync } from 'node:fs';
22	import { serveDir, launch, openApp, frames, pick, pickView } from './lib.mjs';
23	
24	const SHOTS = !process.argv.includes('--no-shots');
25	const SCREENS = fileURLToPath(new URL('./screens/', import.meta.url));
26	const T0 = Date.now(), TOTAL_MS = 60 * 60 * 1000;
27	const problems = [];
28	const check = (name, ok) => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}`); return ok; };
29	const info = (msg) => console.log(`ghi  ${msg}`);
30	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
31	const rd = (rel) => readFileSync(new URL(rel, import.meta.url), 'utf8');
32	
33	/* Thông số lấy từ src/config.ts (đọc chữ, không import TS) để test không chép số tay */
34	const cfgSrc = rd('../src/config.ts'), drv = cfgSrc.slice(cfgSrc.indexOf('const driveBase'));
35	const num = (re, from = drv) => { const m = from.match(re); if (!m) throw new Error('không đọc được thông số: ' + re); return Number(m[1]); };
36	const C = {
37	  length: num(/length:\s*([\d.]+)/), width: num(/width:\s*([\d.]+)/), height: num(/height:\s*([\d.]+)/), stepMax: num(/stepMax:\s*([\d.]+)/),
38	  axisX0: num(/axisX0:\s*(-?\d+)/), axisX1: num(/axisX1:\s*(-?\d+)/), tpX0: num(/tpX0:\s*(-?\d+)/),
39	  spawnX: num(/spawn:\s*\{\s*x:\s*(-?[\d.]+)/), spawnLane: num(/spawn:\s*\{[^}]*lane:\s*([\d.]+)/),
40	  headNight: num(/headNight:\s*([\d.]+)/), tailNight: num(/tailNight:\s*([\d.]+)/), tailBrake: num(/tailBrake:\s*([\d.]+)/), tunnelFar: num(/tunnelFar:\s*([\d.]+)/)
41	};
42	const LANGS = ['vi', 'en', 'ko', 'ja', 'zh', 'th', 'ar', 'hi', 'ru'];
43	const LOC = Object.fromEntries(LANGS.map((c) => [c, JSON.parse(rd(`../src/i18n/locales/${c}.json`))]));
44	
45	/* Chạy một mục: lỗi hoặc quá giờ thì in LỖI rồi đi tiếp */
46	async function section(name, fn, ms = 20 * 60 * 1000) {
47	  if (Date.now() - T0 > TOTAL_MS) { check(`${name}: bỏ qua vì hết giờ tổng ${TOTAL_MS / 60000} phút`, false); return; }
48	  let timer;
49	  try {
50	    await Promise.race([fn(), new Promise((_, rej) => { timer = setTimeout(() => rej(new Error(`quá giờ mục ${ms / 60000} phút`)), ms); })]);
51	  } catch (e) { check(`${name}: ngoại lệ ${String(e && e.message || e).split('\n')[0]}`, false); }
52	  finally { clearTimeout(timer); }
53	}
54	
55	/* ======================= Chạy trong trang: bộ công cụ lái theo kịch bản ======================= */
56	function installHelpers(K) {
57	  const a = window.__app, D = a.drive, T = a.THREE;
58	  const HL = K.length / 2, HW = K.width / 2;
59	  const wrap = (x) => x - 2 * Math.PI * Math.round(x / (2 * Math.PI));
60	  const pad = (id) => D.net.pads.find((p) => p.id === id) || null;
61	  /* mặt đường tại (x, z) ở tầng gần yRef nhất trong ± stepMax; NaN nếu không có (cổng đang đóng thì bỏ ô) */
62	  const ground = (x, z, yRef) => {
63	    let best = NaN, bd = Infinity;
64	    for (const p of D.net.pads) {
65	      if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1) continue;
66	      if (p.gate !== undefined && D.net.closed.has(p.gate)) continue;
67	      const y = p.y(x, z), d = Math.abs(y - yRef);
68	      if (d <= K.stepMax && d < bd) { bd = d; best = y; }
69	    }
70	    return best;
71	  };
72	  const pts = (s, n) => {   // điểm mẫu thân xe: n = 9 (lưới 3 × 3) hoặc 5 (tâm + bốn góc)
73	    const c = Math.cos(s.yaw), sn = Math.sin(s.yaw), out = [];
74	    for (let i = -1; i <= 1; i++) for (let j = -1; j <= 1; j++) {
75	      if (n === 5 && !((i === 0 && j === 0) || (i !== 0 && j !== 0))) continue;
76	      const lf = i * HL, ln = j * HW;
77	      out.push([s.x + lf * c + ln * sn, s.z - lf * sn + ln * c]);
78	    }
79	    return out;
80	  };
81	  /* hộp bao nhà: nhà khu phố (level gần của THREE.LOD) + nhà quanh Thuận Phước (tp-houses), từ ma trận instance và hình học thật của cảnh */
82	  let boxes = null;
83	  const buildBoxes = () => {
84	    const out = [], mi = new T.Matrix4(), mw = new T.Matrix4(), bb = new T.Box3();
85	    a.scene.updateMatrixWorld(true);
86	    a.scene.traverse((o) => {
87	      if (!o.isInstancedMesh) return;
88	      const near = o.parent && o.parent.isLOD && o.parent.levels[0] && o.parent.levels[0].object === o;
89	      if (!near && o.name !== 'tp-houses') return;
90	      if (!o.geometry.boundingBox) o.geometry.computeBoundingBox();
91	      for (let i = 0; i < o.count; i++) {
92	        o.getMatrixAt(i, mi);
93	        const e = mi.elements; if (Math.hypot(e[0], e[1], e[2]) < 1e-6) continue;   // nhà đã dọn (scale 0)
94	        mw.multiplyMatrices(o.matrixWorld, mi);
95	        bb.copy(o.geometry.boundingBox).applyMatrix4(mw);
96	        out.push(bb.min.x, bb.max.x, bb.min.z, bb.max.z, bb.min.y, bb.max.y);
97	      }
98	    });
99	    boxes = new Float64Array(out);
100	    return boxes.length / 6;
101	  };
102	  const inBuilding = (s) => {
103	    const P = pts(s, 5), top = s.y + K.height;
104	    for (let b = 0; b < boxes.length; b += 6) {
105	      if (!(top > boxes[b + 4] + 0.3 && s.y < boxes[b + 5] - 0.3)) continue;
106	      for (const [x, z] of P) if (x > boxes[b] + 0.05 && x < boxes[b + 1] - 0.05 && z > boxes[b + 2] + 0.05 && z < boxes[b + 3] - 0.05) return b / 6;
107	    }
108	    return -1;
109	  };
110	  /* Tia thẳng xuống vào lưới thật (không instance / điểm / đường / xe của chế độ lái) từ trên xe 1 m: cao độ trúng hoặc null */
111	  const rayY = (x, y, z) => {
112	    const list = [];
113	    a.scene.traverse((o) => {
114	      if (!o.isMesh || o.isInstancedMesh || o.isSkinnedMesh) return;
115	      for (let p = o; p; p = p.parent) if (!p.visible || p.name === 'drive-cars') return;
116	      const g = o.geometry; if (!g.boundingSphere) g.computeBoundingSphere();
117	      const sp = g.boundingSphere.clone().applyMatrix4(o.matrixWorld);
118	      if (Math.hypot(sp.center.x - x, sp.center.z - z) > sp.radius + 1) return;
119	      list.push(o);
120	    });
121	    const rc = new T.Raycaster(); rc.layers.enableAll(); rc.set(new T.Vector3(x, y + 1, z), new T.Vector3(0, -1, 0)); rc.near = 0; rc.far = 12;
122	    const h = rc.intersectObjects(list, false);
123	    return h.length ? { y: h[0].point.y, name: h[0].object.name || h[0].object.type } : null;
124	  };
125	  const hidden = [];
126	  const hideTraffic = () => {
127	    let n = 0;
128	    for (const f of a.traffic.fleets()) { const m = f.mesh; if (m && m.visible) { m.visible = false; hidden.push(m); n++; } }
129	    return n;
130	  };
131	  const showTraffic = () => { for (const m of hidden.splice(0)) m.visible = true; };
132	
133	  /* lái thẳng: đặt xe ở (x, z, yaw), ga tới vWant (m/s), kiểm mỗi 0,5 s mô phỏng; rayAt: các tiến độ (m) cần đối chiếu bằng tia */
134	  const run = (o) => {
135	    D.placeAt(o.x, o.z, o.yaw);
136	    const s = D.state, inp = { gas: 0, brake: 0, steer: 0, hand: false }, dirx = Math.cos(o.yaw);
137	    const res = { tag: o.tag, steps: 0, t: 0, nViol: 0, viol: [], reached: false, vmax: 0, stuck: null, checks: 0, rays: 0, x: s.x };
138	    const note = (k, msg) => { res.nViol++; if (res.viol.length < 6) res.viol.push(`${k}: ${msg}`); };
139	    const rayAt = (o.rayAt || []).slice();
140	    let still = 0;
141	    for (let i = 0; i < Math.ceil(o.maxT / 0.1); i++) {
142	      inp.gas = s.v < (o.vWant || 100) ? 1 : 0;
143	      D.step(0.1, inp);
144	      res.steps++; res.t += 0.1; if (s.v > res.vmax) res.vmax = s.v;
145	      const prog = (s.x - o.x) * dirx;
146	      if (res.steps % 5 === 0) {
147	        res.checks++;
148	        const g = ground(s.x, s.z, s.y);
149	        if (Number.isNaN(g)) note('không có mặt đường tại tâm', `(${s.x.toFixed(1)}, ${s.z.toFixed(1)}) y ${s.y.toFixed(2)}`);
150	        else if (Math.abs(g - s.y) > 0.05) note('y lệch mặt đường', `${s.y.toFixed(3)} so ${g.toFixed(3)} tại x ${s.x.toFixed(1)}`);
151	        const bad = pts(s, 9).filter(([x, z]) => Number.isNaN(ground(x, z, s.y))).length;
152	        if (bad) note('thân xe thiếu mặt đường (drFits sai)', `${bad}/9 điểm tại (${s.x.toFixed(1)}, ${s.z.toFixed(1)})`);
153	        if (boxes) { const b = inBuilding(s); if (b >= 0) note('xe nằm trong nhà', `nhà #${b} tại (${s.x.toFixed(1)}, ${s.z.toFixed(1)})`); }
154	      }
155	      while (rayAt.length && prog >= rayAt[0]) {
156	        rayAt.shift(); res.rays++;
157	        const h = rayY(s.x, s.y, s.z);
158	        if (!h) note('tia xuống không trúng lưới nào', `(${s.x.toFixed(1)}, ${s.z.toFixed(1)})`);
159	        else if (Math.abs(h.y - s.y) > 0.12) note('mặt trúng của tia lệch y xe', `${h.name} ${h.y.toFixed(3)} so ${s.y.toFixed(3)} tại x ${s.x.toFixed(1)}`);
160	      }
161	      if (prog >= o.dist) { res.reached = true; break; }
162	      still = res.t > 6 && Math.abs(s.v) < 0.3 ? still + 1 : 0;
163	      if (still > 30) { res.stuck = [+s.x.toFixed(1), +s.z.toFixed(1)]; break; }
164	    }
165	    res.x = +s.x.toFixed(1); res.v = +s.v.toFixed(2);
166	    return res;
167	  };
168	
169	  /* đâm thẳng ở v0: o.pad (id ô), o.side ('z0' | 'z1' | 'x0' | 'x1'): độ lấn lớn nhất của tâm + bốn góc ra ngoài cạnh đó, số bước thân xe thiếu mặt đường */
170	  const crash = (o) => {
171	    const p = pad(o.pad); if (!p) return { err: 'không có ô ' + o.pad };
172	    D.placeAt(o.x, o.z, o.yaw);
173	    const s = D.state, inp = { gas: 1, brake: 0, steer: 0, hand: false };
174	    s.v = o.v0;
175	    let worst = -Infinity, invalid = 0, minZ = Infinity;
176	    for (let i = 0; i < Math.ceil(o.T / 0.1); i++) {
177	      D.step(0.1, inp);
178	      for (const [x, z] of pts(s, 5)) {
179	        const over = o.side === 'z1' ? z - p.z1 : o.side === 'z0' ? p.z0 - z : o.side === 'x1' ? x - p.x1 : p.x0 - x;
180	        if (over > worst) worst = over;
181	        if (z < minZ) minZ = z;
182	      }
183	      if (pts(s, 9).some(([x, z]) => Number.isNaN(ground(x, z, s.y)))) invalid++;
184	    }
185	    return { v: +s.v.toFixed(2), worst: +worst.toFixed(3), invalid, x: +s.x.toFixed(2), z: +s.z.toFixed(2), minZ: +minZ.toFixed(3), pad: [p.x0, p.x1, p.z0, p.z1] };
186	  };
187	
188	  /* lái theo điểm (pure pursuit): wp = [[x, z], ...]; ga giữ vWant, kiểm mỗi bước: đủ 9 điểm mẫu có mặt đường */
189	  const follow = (o) => {
190	    D.placeAt(o.x, o.z, o.yaw);
191	    const s = D.state, inp = { gas: 0, brake: 0, steer: 0, hand: false }, wp = o.wp, n = wp.length;
192	    let k = 0, still = 0, bad = 0, first = null, t = 0, done = false;
193	    for (let i = 0; i < Math.ceil(o.maxT / 0.1); i++) {
194	      while (k < n - 1 && Math.hypot(wp[k][0] - s.x, wp[k][1] - s.z) < 2.5) k++;
195	      const dx = wp[k][0] - s.x, dz = wp[k][1] - s.z;
196	      const err = wrap(Math.atan2(-dz, dx) - s.yaw);
197	      inp.steer = Math.max(-1, Math.min(1, 2.2 * err));
198	      inp.gas = s.v < o.vWant ? 1 : 0; inp.brake = s.v > o.vWant + 2 ? 1 : 0;
199	      D.step(0.1, inp); t += 0.1;
200	      if (pts(s, 9).some(([x, z]) => Number.isNaN(ground(x, z, s.y)))) { bad++; if (!first) first = [+s.x.toFixed(1), +s.z.toFixed(1)]; }
201	      if (k === n - 1 && Math.hypot(wp[k][0] - s.x, wp[k][1] - s.z) < 2.5) { done = true; break; }
202	      still = t > 6 && Math.abs(s.v) < 0.3 ? still + 1 : 0;
203	      if (still > 30) break;
204	    }
205	    return { done, k, n, bad, first, t: +t.toFixed(1), x: +s.x.toFixed(1), z: +s.z.toFixed(1), v: +s.v.toFixed(2) };
206	  };
207	
208	  window.__dr = { pad, ground, pts, buildBoxes, hideTraffic, showTraffic, run, crash, follow, rayY, rect: (id) => { const p = pad(id); return p ? [p.x0, p.x1, p.z0, p.z1] : null; } };
209	}
210	
211	/* Cung nửa vòng tròn / vòng tròn: các điểm trên cung tâm (cx, cz) bán kính r từ góc a0 tới a1 (độ), n đoạn */
212	const arc = (cx, cz, r, a0, a1, n = 12) => Array.from({ length: n + 1 }, (_, i) => { const a = (a0 + (a1 - a0) * i / n) * Math.PI / 180; return [+(cx + r * Math.cos(a)).toFixed(3), +(cz + r * Math.sin(a)).toFixed(3)]; });
213	
214	/* ===================================== chạy ===================================== */
215	const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
216	const browser = await launch();
217	const allErrors = [];   // [trang, lỗi console]
218	try {
219	  if (SHOTS) mkdirSync(SCREENS, { recursive: true });
220	  let A = null;
221	
222	  /* ---------------- Trang A: ?explore=drive ---------------- */
223	  await section('mở trang A', async () => {
224	    A = await openApp(browser, srv.url + '?explore=drive', { width: 640, height: 360 });
225	    A.page.setDefaultTimeout(300000);
226	  }, 15 * 60 * 1000);
227	
228	  if (A) {
229	    const P = A.page;
230	    const shot = async (name) => { if (SHOTS) await P.screenshot({ path: `${SCREENS}drive-check-${name}.png` }); };
231	
232	    await section('1 (?explore=drive)', async () => {
233	      await P.waitForFunction(() => window.__app.drive.state && window.__app.cam.mode === 'car', null, { polling: 500 });
234	      const r = await P.evaluate(() => { const A = window.__app, s = A.drive.state; return { cls: document.body.classList.contains('explore') && document.body.classList.contains('drive'), mode: A.cam.mode, x: s.x, z: s.z, yaw: s.yaw, y: s.y, v: s.v, active: A.drive.active() }; });
235	      check(`1 ?explore=drive: body.explore + body.drive, cam.mode '${r.mode}' = car, drive.active ${r.active}`, r.cls && r.mode === 'car' && r.active);
236	      check(`1 xe ở drSpawnPose(lái một mình): (${r.x}, ${r.z}) = (${C.spawnX}, ${C.spawnLane}), yaw ${r.yaw} (hướng Đông), v ${r.v}`, Math.abs(r.x - C.spawnX) < 1e-6 && Math.abs(r.z - C.spawnLane) < 1e-6 && r.yaw === 0 && r.v === 0);
237	      await frames(P, 2);
238	      await shot('spawn-ngay');
239	    });
240	
241	    await section('2 (lái suốt từng trục)', async () => {
242	      await P.evaluate(installHelpers, C);
243	      const nBox = await P.evaluate(() => window.__dr.buildBoxes());
244	      const nHid = await P.evaluate(() => window.__dr.hideTraffic());
245	      check(`2 oracle nhà: ${nBox} hộp bao nhà (không rỗng), đã ẩn ${nHid} đội xe tự động để không chặn kịch bản`, nBox > 1000 && nHid >= 1);
246	      const AX = [['dragon', 'dragon.bridge', C.axisX0], ['songHan', 'songHan.swing', C.axisX0], ['ttl', 'ttl.bridge', C.axisX0], ['tunnel', 'tunnel.tube', C.axisX0], ['thuanPhuoc', 'thuanPhuoc.bridge', C.tpX0]];
247	      for (const [id, padId, x0] of AX) {
248	        for (const [side, yaw] of [['S', 0], ['N', Math.PI]]) {
