        check(`3 ${label}: lấn ra ngoài mép ô ${r.worst} m (≤ 0,01), v cuối ${r.v} m/s (< 0,5), ${r.invalid} bước thân xe thiếu mặt đường, dừng tại (${r.x}, ${r.z})`, !r.err && r.worst <= 0.01 && Math.abs(r.v) < 0.5 && r.invalid === 0);
      }
