      const r = await P.evaluate(() => {
        const A = window.__app, S = A.stroll, st = S.stroll.state, hud = document.getElementById('drHud'), g = A.scene.getObjectByName('drive-cars');
        return { drive: document.body.classList.contains('drive'), hud: hud.getClientRects().length, stroll: document.body.classList.contains('stroll'), far: A.hr.farDistance, cars: g ? !!g.parent : false,
          valid: S.stValid(S.stroll.map, st.x, st.z, 0), x: st.x, z: st.z, mode: A.cam.mode };
      });
      check(`10 thoát lái rồi vào Đi dạo: body.drive ${r.drive} (false), #drHud ${r.hud} hộp (0), body.stroll ${r.stroll}, nhóm xe còn trong cảnh ${r.cars} (false), ngưỡng xa Hầm ${r.far} = ${far0}, đi dạo ở (${r.x.toFixed(1)}, ${r.z.toFixed(1)}) hợp lệ ${r.valid}`,
        !r.drive && r.hud === 0 && r.stroll && !r.cars && r.far === far0 && r.valid && r.mode === 'stroll');
      allErrors.push(['F', F.errors]);
    } finally { await F.page.close(); }
  }, 20 * 60 * 1000);

  for (const [name, errs] of allErrors) {
    check(`console sạch (trang ${name}, ${errs.length} lỗi)`, errs.length === 0);
    if (errs.length) console.log(errs.join('\n'));
  }
} catch (e) {
  check('ngoại lệ ngoài mục: ' + String(e && e.message || e), false);
} finally {
  try { await browser.close(); } catch { /* bỏ qua */ }
  srv.close();
}
console.log(problems.length ? `drive-check: LỖI (${problems.length}): ${problems.join('; ')}` : 'drive-check: đạt');
process.exit(problems.length ? 1 : 0);

content.content:
1	/* ============================ Lái xe máy: chuyển động xe tay ga có nghiêng ============================
2	   Spec D-040 §5.3 (+ §17.8, §17.9). Giữ khung của drStep (explore/drive/motion.ts): bước con ≤ CONFIG.drive.sim.dt (tối đa sim.steps, phần dư bỏ),
3	   dời thân bằng drMove, mất phần tốc độ hướng vào vật cản một lần mỗi lần chạm, cọ thì hãm thêm perf.scrape; kết quả không phụ thuộc tần số khung.
4	   Khác ô tô: người chơi điều khiển độ nghiêng, không phải góc lái.
5	   - Ga / phanh: throttle, brakeK là lọc bậc một (chính xác theo hàm mũ) của đầu vào; gia tốc dùng trung bình đầu / cuối bước (bậc hai theo h).
6	     Đường cong tăng tốc khớp như drAccel: a0 = 50 km/h / t50 tới 50 km/h, sau đó a0 · v50 / v · (1 − u^k), k giải sao cho 0 → 80 km/h đúng t80.
7	     Phanh / phanh gấp nội suy khô ↔ ướt theo grip. Nhả ga hãm coast. Không có số lùi: đứng yên giữ phanh (không ga) thì dắt lùi ≤ walkBack.
8	   - Tốc độ ≥ vBlend: độ nghiêng đích steer · bkLeanMax(v, grip); lean theo lò xo giảm chấn tới hạn, giải đúng dạng đóng mỗi bước
9	     (ổn định với mọi h, kể cả 0,1 s); tần số nội suy leanHz → leanHzFast theo v / vMax (nặng tay khi nhanh); độ cong quỹ đạo g · tan(lean) / v².
10	   - Dưới vBlend: trộn tuyến tính theo v / vBlend với lái động học kiểu xe đạp (góc lái steer tiến về đích theo steerRate, trả theo steerReturn,
11	     bán kính trục sau nhỏ nhất turnRadius); độ nghiêng đích phần động học atan(v²κ / g). Độ cong từ độ nghiêng kẹp ≤ 1 / turnRadius nên đứng yên
12	     mà còn nghiêng cũng không xoay tại chỗ. bkLeanMax kẹp tan(lean) ≤ v² / (g · turnRadius): bán kính rẽ không nhỏ hơn bán kính hình học.
13	   - Giảm xóc trước / sau (chỉ hình + camera): lò xo giảm chấn, Euler ẩn; đích theo gia tốc dọc (phanh chúi đầu, ga nhún đuôi) + nhiễu mặt đường
14	     rng(sus.seed) theo tốc độ; độ dốc đổi (mối nối ô) hích vận tốc. Vòng tua theo bkRpm, trễ tauUp / tauDown.
15	   - Xi nhan tự tắt khi đã rẽ quá cancelYaw theo hướng xi nhan rồi trả thẳng, hoặc đi thẳng quá cancelS. stuck: s bị chặn mà vẫn vặn ga.
16	   - Thân va chạm: người gọi đặt drUseBody(BK_BODY) trước; bkStep không đổi thân. Sơ tán nhịp quay Cầu sông Hàn: drEvacStep rồi lean = 0.
17	   Quy ước hướng như ô tô: yaw = 0 mũi +X, vectơ tiến (cos yaw, −sin yaw); steer > 0 / lean > 0 = rẽ / nghiêng trái.
18	   Không cấp phát mỗi khung (D-018). Không import three. */
19	import { CONFIG } from '../../config';
20	import { rng } from '../../common/math';
21	import { drGround, type DrNet } from '../drive/net';
22	import { drMove, type DrBody, type DrPose, type DrBox } from '../drive/collide';
23	import { drCreate, drEvacStep, type DrState } from '../drive/motion';
24	
25	export interface BkInput { gas: number; brake: number; steer: number; hard: boolean; grip: number }   // gas, brake 0..1; steer −1..1 (trái +); hard: phanh gấp; grip 0 (ướt hẳn)..1 (khô)
26	export interface BkState extends DrState { lean: number; leanV: number; susF: number; susFV: number; susR: number; susRV: number; rpm: number; throttle: number; brakeK: number; acc: number; sig: -1 | 0 | 1; sigYaw: number; sigT: number; stuck: number }   // lean: rad (trái +), leanV: rad/s; susF / susR: m lún giảm xóc (+ = nén), susFV / susRV: m/s; rpm: vòng/phút; throttle, brakeK: 0..1 đã làm mượt; acc: m/s² gia tốc dọc; sig: xi nhan −1 phải / 0 / 1 trái; sigYaw: rad đã rẽ theo hướng xi nhan; sigT: s đi thẳng kể từ lúc bật / lần rẽ cuối; stuck: s bị chặn mà vẫn vặn ga
27	
28	const B = CONFIG.bike.body, P = CONFIG.bike.perf, CVT = CONFIG.bike.cvt, SUS = CONFIG.bike.sus, SG = CONFIG.bike.signal, SIM = CONFIG.drive.sim;
29	const L = B.wheelbase, G = P.latG;
30	export const BK_BODY: DrBody = { hl: B.length / 2, hw: B.width / 2, ax: B.wheelbase / 2, height: B.height };
31	const V50 = 50 / 3.6, V80 = 80 / 3.6;                                // m/s — mốc t50, t80
32	const STEER_MAX = Math.atan(L / P.turnRadius);                       // rad — góc lái lớn nhất: bán kính trục sau = turnRadius
33	const KAPPA_MAX = 1 / P.turnRadius;                                  // 1/m — độ cong lớn nhất
34	const SUS_W = 2 * Math.PI * SUS.hz;
35	const NOISE = rng(SUS.seed);                                         // nhiễu mặt đường, chuỗi riêng (không dùng rand())
36	
37	/* ===== Đường cong tăng tốc ===== */
38	let A0 = NaN, KEXP = NaN;                                            // a0 (m/s²) và số mũ k, giải lười ở lần gọi đầu
39	function bkAccelK(v: number, k: number): number {
40	  if (v <= V50) return A0;
41	  if (v >= P.vMax) return 0;
42	  const u = (v - V50) / (P.vMax - V50);
43	  return A0 * V50 / v * (1 - Math.pow(u, k));
44	}
45	/* Thời gian 0 → 80 km/h với số mũ k (tích phân dv / a, điểm giữa) */
46	function bkT80(k: number): number {
47	  const N = 2000, h = (V80 - V50) / N;
48	  let t = V50 / A0;
49	  for (let i = 0; i < N; i++) t += h / bkAccelK(V50 + (i + 0.5) * h, k);
50	  return t;
51	}
52	function bkFitAccel(): void {
53	  A0 = V50 / P.t50;
54	  let lo = 0.2, hi = 50;                                             // k nhỏ ⇒ hãm sớm ⇒ chậm hơn: bkT80 giảm theo k
55	  for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; if (bkT80(m) > P.t80) lo = m; else hi = m; }
56	  KEXP = (lo + hi) / 2;
57	}
58	/* m/s² khi vặn hết ga ở tốc độ v ≥ 0 */
59	export function bkAccel(v: number): number {
60	  if (Number.isNaN(KEXP)) bkFitAccel();
61	  return bkAccelK(v, KEXP);
62	}
63	
64	/* rad — độ nghiêng lớn nhất ở tốc độ v với độ bám grip: khô ↔ ướt, kẹp để bán kính rẽ không nhỏ hơn turnRadius */
65	export function bkLeanMax(v: number, grip: number): number {
66	  const g = grip > 1 ? 1 : grip < 0 ? 0 : grip, m = P.leanMaxWet + (P.leanMax - P.leanMaxWet) * g;
67	  const geom = Math.atan(v * v / (G * P.turnRadius));
68	  return geom < m ? geom : m;
69	}
70	
71	/* vòng/phút — vòng tua đích của hộp số vô cấp ở tốc độ v (m/s, dấu bỏ qua) và tay ga throttle (0..1).
72	   Nhả ga: theo tỉ số truyền (idle → engage tới engageV, rồi engage → max tới vMax). Vặn ga: ly tâm trượt ở engage lúc đứng,
73	   tua lên vùng công suất power khi xe nhích tới engageV, rồi giữ power cho tới khi đường tỉ số vượt lên. */
74	export function bkRpm(v: number, throttle: number): number {
75	  const a = Math.abs(v), t = throttle > 1 ? 1 : throttle < 0 ? 0 : throttle;
76	  const line = a <= CVT.engageV ? CVT.idle + (CVT.engage - CVT.idle) * a / CVT.engageV
77	    : Math.min(CVT.max, CVT.engage + (CVT.max - CVT.engage) * (a - CVT.engageV) / (P.vMax - CVT.engageV));
78	  const full = Math.max(line, CVT.engage + (CVT.power - CVT.engage) * Math.min(1, a / CVT.engageV));
79	  return line + t * (full - line);
80	}
81	
82	/* Bật xi nhan hướng dir (1 trái, −1 phải, 0 tắt); bấm lại cùng hướng thì tắt */
83	export function bkSignal(s: BkState, dir: -1 | 0 | 1): void {
84	  s.sig = dir !== 0 && s.sig === dir ? 0 : dir;
85	  s.sigYaw = 0; s.sigT = 0;
86	}
87	
88	const bkToward0 = (v: number, d: number): number => v > 0 ? (v > d ? v - d : 0) : (v < -d ? v + d : 0);
89	
90	/* Dốc dọc từ cao độ mặt đường tại trục trước / sau (dương = mũi cao hơn đuôi, như ô tô); giữ giá trị cũ nếu một trục không có mặt đường cùng tầng */
91	export function bkPitch(s: BkState, net: DrNet): void {
92	  const fx = Math.cos(s.yaw) * L / 2, fz = -Math.sin(s.yaw) * L / 2;
93	  const yf = drGround(net, s.x + fx, s.z + fz, s.y), yr = drGround(net, s.x - fx, s.z - fz, s.y);
94	  if (!Number.isNaN(yf) && !Number.isNaN(yr)) s.pitch = Math.atan2(yf - yr, L);
95	}
96	
97	/* Xe mới ở chỗ xuất phát của slot (như ô tô), đứng yên, thẳng đứng */
98	export function bkCreate(net: DrNet, slot: number): BkState {
99	  const c = drCreate(net, slot);
100	  const s: BkState = { ...c, lean: 0, leanV: 0, susF: 0, susFV: 0, susR: 0, susRV: 0, rpm: CVT.idle, throttle: 0, brakeK: 0, acc: 0, sig: 0, sigYaw: 0, sigT: 0, stuck: 0 };
101	  bkPitch(s, net);
102	  return s;
103	}
104	
105	/* Về tim làn bên phải của ô mặt đường gần nhất (khoảng cách mặt bằng + chênh cao độ), đứng yên, thẳng đứng.
106	   Chiều đi theo hậu tố id ô (roadData.ts: .S đi Đông, .N đi Tây, .W đi Nam, .E đi Bắc; đi bên phải); ô không có hậu tố (nút giao)
107	   thì dọc cạnh dài, chiều gần hướng xe nhất. Tim làn bên phải = tim ô lệch về bên phải một phần tư bề rộng ô. Không có ô nào thì false */
108	export function bkRecover(s: BkState, net: DrNet): boolean {
109	  const pads = net.pads;
110	  let best = -1, bestD = Infinity;
111	  for (let i = 0; i < pads.length; i++) {
112	    const p = pads[i];
113	    if (p.gate !== undefined && net.closed.has(p.gate)) continue;
114	    const cx = s.x < p.x0 ? p.x0 : s.x > p.x1 ? p.x1 : s.x, cz = s.z < p.z0 ? p.z0 : s.z > p.z1 ? p.z1 : s.z;
115	    const d = Math.hypot(cx - s.x, cz - s.z) + Math.abs(p.y(cx, cz) - s.y);
116	    if (d < bestD) { bestD = d; best = i; }
117	  }
118	  if (best < 0) return false;
119	  const p = pads[best], tag = p.id.slice(p.id.lastIndexOf('.') + 1);
120	  let yaw: number;
121	  if (tag === 'S') yaw = 0; else if (tag === 'N') yaw = Math.PI; else if (tag === 'W') yaw = -Math.PI / 2; else if (tag === 'E') yaw = Math.PI / 2;
122	  else if (p.x1 - p.x0 >= p.z1 - p.z0) yaw = Math.cos(s.yaw) >= 0 ? 0 : Math.PI;
123	  else yaw = Math.sin(s.yaw) >= 0 ? Math.PI / 2 : -Math.PI / 2;
124	  const alongX = Math.abs(Math.cos(yaw)) > 0.5, hl = BK_BODY.hl;
125	  const rx = Math.sin(yaw), rz = Math.cos(yaw);                     // vectơ sang phải
126	  const mx = (p.x0 + p.x1) / 2, mz = (p.z0 + p.z1) / 2;
127	  const clampIn = (a: number, a0: number, a1: number) => a1 - a0 <= 2 * hl ? (a0 + a1) / 2 : a < a0 + hl ? a0 + hl : a > a1 - hl ? a1 - hl : a;
128	  s.x = alongX ? clampIn(s.x, p.x0, p.x1) : mx + rx * (p.x1 - p.x0) / 4;
129	  s.z = alongX ? mz + rz * (p.z1 - p.z0) / 4 : clampIn(s.z, p.z0, p.z1);
130	  s.y = p.y(s.x, s.z); s.yaw = yaw;
131	  s.v = 0; s.steer = 0; s.lean = 0; s.leanV = 0; s.throttle = 0; s.brakeK = 0; s.acc = 0; s.braking = false;
132	  s.slide = 1; s.touch = 0; s.stuck = 0;
133	  bkPitch(s, net);
134	  return true;
135	}
136	
137	const MOVED: DrPose = { x: 0, y: 0, z: 0, yaw: 0 };
138	
139	/* Một bước h ≤ sim.dt */
140	function bkStep1(s: BkState, inp: BkInput, net: DrNet, boxes: DrBox[], nBoxes: number, h: number): void {
141	  const gas = inp.gas > 0 ? (inp.gas < 1 ? inp.gas : 1) : 0, bIn = inp.hard ? 1 : inp.brake > 0 ? (inp.brake < 1 ? inp.brake : 1) : 0;
142	  const grip = inp.grip > 1 ? 1 : inp.grip < 0 ? 0 : inp.grip === inp.grip ? inp.grip : 1;   // NaN ⇒ khô
143	  /* ga, phanh làm mượt; trung bình trong bước */
144	  const t0 = s.throttle, b0 = s.brakeK;
145	  s.throttle = gas + (t0 - gas) * Math.exp(-h / P.throttleTau);
146	  s.brakeK = bIn + (b0 - bIn) * Math.exp(-h / P.brakeTau);
147	  const thr = (t0 + s.throttle) / 2, bk = (b0 + s.brakeK) / 2;
148	  const rate = inp.hard ? P.hardBrakeWet + (P.hardBrake - P.hardBrakeWet) * grip : P.brakeWet + (P.brake - P.brakeWet) * grip;
149	  /* tốc độ */
150	  const v0 = s.v;
151	  let v = v0;
152	  if (v < 0 || (v <= SIM.revV && bIn > 0 && gas === 0)) {
153	    if (bIn > 0 && gas === 0) {
154	      if (v > 0) v = Math.max(0, v - bk * rate * h);                  // phanh nốt rồi mới dắt lùi
155	      else { const tgt = -P.walkBack * bk; v = v > tgt ? Math.max(tgt, v - P.walkBack * h) : Math.min(tgt, v + P.walkBack * h); }
156	    } else v = bkToward0(v, (P.coast + thr * P.walkBack) * h);        // nhả / vặn ga khi đang dắt lùi: về 0
157	  } else {
158	    const a = thr * bkAccel(v) - bk * rate - (v > 0 ? (1 - thr) * P.coast : 0);   // hãm nhả ga chỉ khi đang chạy: đứng yên vặn ga thì nhích ngay
159	    v = v + a * h;
160	    v = v < 0 ? 0 : v > P.vMax ? P.vMax : v;
161	  }
162	  s.acc = (v - v0) / h;
163	  const vm = (v0 + v) / 2, av = vm > 0 ? vm : 0, w = av < P.vBlend ? av / P.vBlend : 1;
164	  /* ghi đông (lái động học khi chậm) */
165	  const want = inp.steer > 1 ? 1 : inp.steer < -1 ? -1 : inp.steer === inp.steer ? inp.steer : 0;   // NaN ⇒ thẳng
166	  let st = s.steer;
167	  if (want === 0) st = bkToward0(st, P.steerReturn * STEER_MAX * h);
168	  else {
169	    const tgt = want * STEER_MAX, back = Math.abs(tgt) < Math.abs(st) || tgt * st < 0;
170	    const d = (back ? Math.max(P.steerRate, P.steerReturn) : P.steerRate) * STEER_MAX * h;
171	    st = st < tgt ? Math.min(tgt, st + d) : Math.max(tgt, st - d);
172	  }
173	  const kKin = Math.tan(st) / L;
174	  /* độ nghiêng: lò xo giảm chấn tới hạn, nghiệm đúng trên bước h với đích giữ nguyên */
175	  const tgtLean = w * want * bkLeanMax(av, grip) + (1 - w) * Math.atan(av * av * kKin / G);
176	  const om = 2 * Math.PI * (P.leanHz + (P.leanHzFast - P.leanHz) * Math.min(1, av / P.vMax));
177	  const l0 = s.lean, A = l0 - tgtLean, Bc = s.leanV + om * A, e = Math.exp(-om * h);
178	  let lean = tgtLean + (A + Bc * h) * e, leanV = (Bc - om * (A + Bc * h)) * e;
179	  if (lean > P.leanMax) { lean = P.leanMax; leanV = 0; } else if (lean < -P.leanMax) { lean = -P.leanMax; leanV = 0; }
180	  /* độ cong: trộn độ cong từ độ nghiêng (kẹp ≤ 1 / turnRadius) với độ cong động học; xoay = độ cong × quãng */
181	  const tl = Math.tan((l0 + lean) / 2);
182	  let kLean = av > 1e-6 ? G * tl / (av * av) : 0;
183	  if (kLean > KAPPA_MAX) kLean = KAPPA_MAX; else if (kLean < -KAPPA_MAX) kLean = -KAPPA_MAX;
184	  const kappa = vm >= 0 ? w * kLean + (1 - w) * kKin : kKin;        // dắt lùi: chỉ động học
185	  /* dời thân xe */
186	  const dist = vm * h, f = drMove(net, s, dist, dist * kappa, boxes, nBoxes, MOVED);
187	  const dyaw = MOVED.yaw - s.yaw;
188	  s.x = MOVED.x; s.y = MOVED.y; s.z = MOVED.z; s.yaw = MOVED.yaw;
189	  /* va chạm: như drStep1 của ô tô */
190	  let slide = s.slide ?? 1, touch = s.touch ?? 0;
191	  if (f < 1) {
192	    if (touch > 0) v = bkToward0(v, P.scrape * h);
193	    const q = f > 0 ? Math.sqrt(f) : 0;
194	    if (q === 0) v = 0;
195	    else if (q < slide) v *= q / slide;
196	    if (q < slide) slide = q;
197	    touch = SIM.touch;
198	  } else if (touch > 0) { touch -= h; if (touch <= 0) { touch = 0; slide = 1; } }
199	  s.slide = slide; s.touch = touch;
200	  s.v = v; s.steer = st; s.lean = lean; s.leanV = leanV; s.braking = bIn > 0;
201	  s.wheel += dist * f / (B.wheelDia / 2);
202	  /* bị chặn mà vẫn vặn ga */
203	  s.stuck = gas > 0 && touch > 0 && Math.abs(v) < 1 ? s.stuck + h : 0;
204	  /* độ dốc, giảm xóc */
205	  const p0 = s.pitch;
206	  bkPitch(s, net);
207	  const kick = SUS.bumpK * (s.pitch - p0) * Math.abs(vm), n = SUS.noise * Math.min(1, Math.abs(v) / P.vMax);
208	  const den = 1 + 2 * SUS.damp * SUS_W * h + SUS_W * SUS_W * h * h;
209	  const tF = -s.acc * SUS.diveK + (NOISE() * 2 - 1) * n, tR = s.acc * SUS.diveK + (NOISE() * 2 - 1) * n;
210	  s.susFV = (s.susFV + kick + h * SUS_W * SUS_W * (tF - s.susF)) / den; s.susF += h * s.susFV;
211	  s.susRV = (s.susRV + kick + h * SUS_W * SUS_W * (tR - s.susR)) / den; s.susR += h * s.susRV;
212	  if (s.susF > SUS.travel) { s.susF = SUS.travel; s.susFV = 0; } else if (s.susF < -SUS.travel) { s.susF = -SUS.travel; s.susFV = 0; }
213	  if (s.susR > SUS.travel) { s.susR = SUS.travel; s.susRV = 0; } else if (s.susR < -SUS.travel) { s.susR = -SUS.travel; s.susRV = 0; }
214	  /* vòng tua */
215	  const rt = bkRpm(v, s.throttle);
216	  s.rpm = rt + (s.rpm - rt) * Math.exp(-h / (rt > s.rpm ? CVT.tauUp : CVT.tauDown));
217	  /* xi nhan */
218	  if (s.sig !== 0) {
219	    s.sigYaw += dyaw * s.sig;
220	    if (s.sigYaw >= SG.cancelYaw && want * s.sig <= 0) { s.sig = 0; s.sigYaw = 0; s.sigT = 0; }
221	    else if (dyaw * s.sig > 0.05 * h) s.sigT = 0;                   // đang rẽ theo hướng xi nhan (> 0,05 rad/s)
222	    else if ((s.sigT += h) > SG.cancelS) { s.sig = 0; s.sigYaw = 0; s.sigT = 0; }
223	  }
224	}
225	
226	/* Bước mô phỏng cho khung dài dt (s). Đang / cần sơ tán khỏi nhịp quay thì khung dành cho sơ tán (đầu vào bỏ qua), xe thẳng đứng */
227	export function bkStep(s: BkState, inp: BkInput, net: DrNet, boxes: DrBox[], nBoxes: number, dt: number): void {
228	  if (drEvacStep(s, net, dt)) { s.lean = 0; s.leanV = 0; s.throttle = 0; s.brakeK = 0; s.acc = 0; s.stuck = 0; return; }
229	  let rem = dt;
230	  for (let k = 0; k < SIM.steps && rem > 1e-6; k++) {
231	    const h = rem < SIM.dt ? rem : SIM.dt;
232	    bkStep1(s, inp, net, boxes, nBoxes, h);
233	    rem -= h;
234	  }
235	}
236

