186	
187	/* Xe đang ở ô hầm không: ô chứa (x, z) có cao độ gần y nhất trong ± stepMax (như drive/net.ts drPadAt), kiểu 'tunnel'. Duyệt tuyến tính, không cấp phát */
188	function bkInTunnel(n: DrNet, s: BkState): boolean {
189	  const step = CONFIG.drive.stepMax;
190	  let best = -1, bestD = Infinity;
191	  for (let i = 0; i < n.pads.length; i++) {
192	    const p = n.pads[i];
193	    if (s.x < p.x0 || s.x > p.x1 || s.z < p.z0 || s.z > p.z1 || (p.gate !== undefined && n.closed.has(p.gate))) continue;
194	    const d = Math.abs(p.y(s.x, s.z) - s.y);
195	    if (d <= step && d < bestD) { best = i; bestD = d; }
196	  }
197	  return best >= 0 && n.pads[best].kind === 'tunnel';
198	}
199	/* Trong ô hầm thì đã ở đoạn có mái chưa (ngoài |x| > coverHalf là dốc hở: mưa, mặt ướt) */
200	const bkCovered = (s: BkState): boolean => Math.abs(s.x) <= HR.coverHalf;
201	
202	/* Người lái theo xe (sau model.place): tín hiệu từ trạng thái chuyển động */
203	function riderStep(s: BkState, dt: number): void {
204	  if (!rider || !model) return;
205	  _sig.lean = s.lean; _sig.acc = s.acc; _sig.susF = s.susF; _sig.susR = s.susR; _sig.steer = s.steer;
206	  rider.update(model, _sig, dt);
207	}
208	
209	/* Mắt góc thứ nhất theo người lái: đo một lần khi có người lái thật trên mô hình thật. Đặt xe về tư thế nghỉ (thẳng đứng, không lái, giảm xóc 0),
210	   người lái tư thế ngồi nền (lò xo phản ứng chưa chạy với người mới), giữa hai xương mắt (+ cam1.eyeFore; không có thì xương đầu + cam1.headEye)
211	   → hệ thân xe (nhóm ngoài: yaw · dốc, dốc = 0); rồi đặt lại như cũ */
212	function riderEye(): void {
213	  const s = state, r = rider, m = model;
214	  if (!r || !m || !m.real) { if (eyeFor) { eyeFor = null; bkCamSetEye(null); } return; }
215	  if (eyeFor === r || !s) return;
216	  eyeFor = r;
217	  _rest.x = s.x; _rest.y = s.y; _rest.z = s.z; _rest.yaw = s.yaw;
218	  m.place(_rest);
219	  r.update(m, _sig0, 0);
220	  r.setFirstPerson(false);
221	  const eyes = r.eyeLocal(m.group, _eye);
222	  bkCamSetEye(eyes ? { fore: _eye.x + C1.eyeFore, up: _eye.y } : { fore: _eye.x + C1.headEye.fore, up: _eye.y + C1.headEye.up });
223	  m.place(s);
224	  riderStep(s, 0);
225	}
226	
227	/* Nạp người lái theo nhân vật đã chọn (stChar, chung với Đi dạo). Về sau stop() / start() khác thì bỏ; nhân vật đổi thì thay người cũ */
228	function riderNeed(): void {
229	  const ch = stChar.get(), gen = ++riderGen;
230	  if (rider && riderCh === ch) return;
231	  void bkRiderLoad(ch).then((src) => {
232	    if (gen !== riderGen || state === null || !src) return;
233	    try {
234	      const r = new BkRider(src);
235	      rider?.dispose(); rider = r; riderCh = ch;
236	      riderStep(state, 0);
237	    } catch (e) { console.warn('Lái xe máy: không dựng được người lái', e); }
238	  });
239	}
240	
241	/* Xe đứng yên ở (x, z) hướng yaw, trạng thái mới; y bỏ trống thì lấy mặt đường cao nhất tại đó. Cho test (__app.bike) và đặt lại vị trí */
242	function bkPlaceAt(x: number, z: number, yaw: number, y?: number): void {
243	  if (!net || !model) return;
244	  const s = bkCreate(net, BK_SOLO_SLOT);
245	  let gy = -Infinity;
246	  for (const p of net.pads) {
247	    if (x < p.x0 || x > p.x1 || z < p.z0 || z > p.z1 || (p.gate !== undefined && net.closed.has(p.gate))) continue;
248	    gy = Math.max(gy, p.y(x, z));
249	  }
250	  s.x = x; s.z = z; s.yaw = yaw; s.y = y ?? (Number.isFinite(gy) ? gy : CONFIG.roadY);
251	  bkPitch(s, net);
252	  state = s;
253	  bkCamReset();
254	  model.place(s);
255	  riderStep(s, 0);
256	  riderEye();
257	  if (bkCamPlace(camera, s, camB, net, 0, true)) onResize();
258	  controls.target.set(s.x, s.y, s.z);
259	}
260	
261	/* Trạng thái camera về đầu (giữ góc nhìn đang chọn, trộn xong ngay) */
262	function bkCamReset(): void {
263	  const v = camB.view;
264	  Object.assign(camB, bkCamCreate());
265	  camB.view = v; camB.mix = v === 3 ? 1 : 0;
266	}
267	
268	export const bike = {
269	  active,
270	  inMode,
271	  get state(): BkState | null { return state; },
272	  get net(): DrNet | null { return net; },
273	  get model(): BkBike | null { return model; },   // hình xe của mình (test: real, anchors)
274	  get rider(): BkRider | null { return rider; },  // người lái (test: debug(), setFirstPerson)
275	  get view(): 1 | 3 { return camB.view; },
276	  get cam(): BkCam { return camB; },               // test: mix, roll, bob, surge, yaw / pitch nhìn quanh
277	  get dash(): BkDash | null { return dash; },
278	  get cfg(): typeof CONFIG.bike { return CONFIG.bike; },   // test / kiểm tay: chỉnh số camera lúc chạy
279	  get sound(): typeof bkSound { return bkSound; },        // test: nodes(), on, graph
280	  get fx(): typeof bkFx { return bkFx; },                 // test: drawn() (vệt pha, số hạt bụi nước), group
281	  /* Đổi góc nhìn: trộn vị trí + hướng + fov + near trong cam1.mixS, không dừng xe */
282	  setView(v: 1 | 3): void { camB.view = v === 3 ? 3 : 1; },
283	  get watching(): boolean { return watching; },
284	  /* Vào lái: một mình (không phiên / ngoại tuyến) hoặc với slot lái vừa được cấp (xuất phát theo slot) */
285	  start(): void {
286	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
287	    const n = drEnsureNet();   // dựng net trước: lỗi ở đây thì thân va chạm vẫn là ô tô (mạng đường không phụ thuộc thân xe)
288	    drUseBody(BK_BODY);
289	    net = n;
290	    const ses = exMulti.session;
291	    const slot = ses && ses.kind === 'drive' && ses.mySlot >= 0 ? ses.mySlot : BK_SOLO_SLOT;
292	    if (ses) exMulti.onChange = bkOnMultiChange;
293	    exDrivers.setSelf(-1);    // xe của mình không nằm trong drCars (model.ts vẽ)
294	    state = bkCreate(n, slot);
295	    camB.view = 1; bkCamReset();
296	    motionK = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches ? C1.motionReduced : C1.motion;
297	    if (!model) model = new BkBike();
298	    if (!dash) dash = new BkDash();
299	    scene.add(model.group);
300	    model.place(state);
301	    scene.add(bkFx.group); bkFx.start(n);
302	    bkRoadSet(true);                          // hạt nhựa + vệt ướt trên vật liệu đường (roadFx.ts; uRoadNear = 1 nếu CONFIG.bike.road.detail)
303	    riderNeed();
304	    riderStep(state, 0);
305	    driveView.far = CONFIG.drive.tunnelFar;   // mặt đường hầm hiện ở nút giao với hai đường dọc mới, như ô tô
306	    bkKeys.clear(); touch?.reset(); hornTouch = false;
307	    drHudShow(n); bkHudShow(); bkSound.start();
308	    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
309	    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
310	    riderEye();
311	    bkCamPlace(camera, state, camB, n, 0, true); onResize();   // fov / near góc thứ nhất; onResize cập nhật ma trận chiếu và hệ số cỡ điểm
312	    controls.target.set(state.x, state.y, state.z);
313	    document.body.classList.add('explore', 'drive', 'bike');
314	  },
315	  /* Chế độ xem bám xe người khác (hết chỗ lái, hoặc vừa nhường chỗ do rời máy): cam.mode = 'bike' nhưng không có xe / trạng thái của mình, không đọc phím, không tiếng máy;
316	     carry = true khi vừa nhường chỗ (camera đang ở sau xe cũ, trượt dần sang xe được xem). Không có phiên thì không làm gì */
317	  startWatching(carry = false): void {
318	    const s = exMulti.session; if (!s) return;
319	    const n = drEnsureNet();
320	    net = n;
321	    if (state !== null) {   // vừa nhường chỗ: cất xe, người lái, hiệu ứng, tiếng của mình
322	      riderGen++; rider?.setFirstPerson(false);
323	      model?.group.removeFromParent(); bkFx.stop(); bkSound.stop(); bkHudHide();
324	    }
325	    state = null; watching = true; chased = carry;
326	    bkKeys.clear(); touch?.reset(); hornTouch = false;
327	    bkRoadSet(false);                         // hạt nhựa + vệt ướt chỉ khi tự lái
328	    exDrivers.setSelf(-1);
329	    driveView.far = CONFIG.drive.tunnelFar;
330	    drHudShow(n);
331	    if (!saved) saved = { fov: camera.fov, near: camera.near, explore: document.body.classList.contains('explore') };
332	    cam.flight.then = null; cam.mode = 'bike'; controls.enabled = false;
333	    camW.yaw = 0; camW.pitch = 0; camW.idle = 0;
334	    document.body.classList.add('explore', 'drive', 'bike', 'ex-watching');
335	    exMulti.onChange = bkOnMultiChange;
336	    exWatchShow(s);
337	  },
338	  update(dt: number): void {
339	    if (watching) { watchStep(dt); return; }
340	    if (!active()) return;
341	    bkInputFromKeys(bkKeys, _inp);
342	    bkTouchMerge(_inp, _dr, readTouch);   // gộp cảm ứng, không xóa phím (máy lai)
343	    bkSound.horn(bkKeys.has('KeyH') || hornTouch);
344	    const s = state!, tun = bkInTunnel(net!, s) && bkCovered(s), wd = weatherU.uWindDir.value;
345	    _inp.grip = bkGrip(weatherU.uWet.value, tun);                                       // mặt ướt (trễ theo mưa); đoạn hầm kín luôn khô
346	    _inp.steer += bkGustSteer(s.v, weatherU.uGust.value, wd[0], wd[1], s.yaw);        // gió giật đẩy nhẹ độ nghiêng (≤ fx.gust.steer)
347	    advance(dt, _inp);
348	  },
349	  /* Gọi ngay sau lệnh vẽ khung chính (main.ts); chỗ cho mặt đồng hồ / chụp ảnh của task sau */
350	  afterRender(): void { /* chưa có việc */ },
351	  /* Rời chế độ: trả mọi thứ đã đổi, kể cả khi cam.mode đã bị chỗ khác đổi khỏi 'bike' */
352	  stop(): void {
353	    if (state === null && !watching) return;
354	    state = null; bkKeys.clear(); touch?.reset(); hornTouch = false; riderGen++;
355	    document.getElementById('bkHorn')?.classList.remove('on');   // thoát khi đang giữ 📢: tắt sáng nút ngay, không chờ ngón nhả
356	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
357	    exDrivers.clear(); drCars.clear(); drCars.group.removeFromParent(); exDrivers.bikes.removeFromParent();   // xe người khác (ô tô, xe máy)
358	    bkSound.stop();
359	    bkHudHide();
360	    rider?.setFirstPerson(false);
361	    drHudHide();
362	    model?.group.removeFromParent();
363	    bkFx.stop();
364	    bkRoadSet(false);                         // uRoadNear = 0: vật liệu đường về đúng ảnh cũ
365	    driveView.far = 1;
366	    drUseBody(DR_CAR_BODY);
367	    document.body.classList.remove('drive', 'bike');
368	    if (saved) {
369	      if (!saved.explore) document.body.classList.remove('explore');
370	      camera.fov = saved.fov; camera.near = saved.near; onResize();   // onResize tính lại ma trận chiếu theo fov / near cũ
371	      saved = null;
372	    }
373	    if (cam.mode === 'bike') { cam.mode = 'orbit'; controls.enabled = true; }
374	  },
375	  /* Cho test: như update nhưng nhận đầu vào trực tiếp; đặt xe tại chỗ */
376	  step(dt: number, inp: BkInput): void { if (active()) advance(dt, inp); },
377	  placeAt: bkPlaceAt,
378	  /* Nạp mô hình thật (scooter.glb) và nhân vật người lái sớm, khi chọn thẻ Xe máy */
379	  preload(): void { void bkModelLoad(); void bkRiderLoad(stChar.get()); }
380	};
381	
382	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
383	export function setupBike(c: SwingController, onExit: () => void): void {
384	  ctrl = c; exit = onExit;
385	  window.addEventListener('keydown', (e) => {
386	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung)
387	    if (e.ctrlKey || e.metaKey || e.altKey) return;
388	    if (isField(e.target)) return;
389	    if (!BK_KEYS.has(e.code)) return;
390	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
391	    if (e.code.startsWith('Arrow') || e.code === 'Space') e.preventDefault();   // không cuộn trang, Space không bấm nút đang focus
392	    bkKeys.add(e.code);
393	    if (e.repeat) return;
394	    /* phím một lần (không theo giữ): về làn, xi nhan, góc nhìn */
395	    if (e.code === 'KeyR') bkRecover(state!, net!);
396	    else if (e.code === 'KeyQ') bkSignal(state!, 1);
397	    else if (e.code === 'KeyE') bkSignal(state!, -1);
398	    else if (e.code === 'KeyV') bike.setView(camB.view === 3 ? 1 : 3);
399	  });
400	  window.addEventListener('keyup', (e) => {
401	    bkKeys.delete(e.code);
402	    if (e.code === 'Space' && active() && !isField(e.target)) e.preventDefault();
403	  });
404	  const drop = drBindDrop(window, document, bkKeys);
405	  const hornOff = () => { hornTouch = false; bkSound.horn(false); if (hornBtn) hornBtn.classList.remove('on'); };
406	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) { drop(); touch?.reset(); hornOff(); } });
407	  window.addEventListener('blur', hornOff);
408	  document.addEventListener('visibilitychange', () => { if (document.hidden) hornOff(); });
409	  /* HUD riêng: xi nhan, góc nhìn, về làn bấm một lần (click: chuột, chạm, bàn phím); còi giữ (con trỏ riêng, nhả / hủy / mất capture là thôi) */
410	  const d = (id: string) => document.getElementById(id);
411	  const hornBtn = d('bkHorn');
412	  bkHudBind({ sigL: d('bkSigL'), sigR: d('bkSigR'), stuck: d('bkStuck'), reset: d('bkReset') });
413	  const onClick = (id: string, f: () => void) => d(id)?.addEventListener('click', () => { if (active()) { exMulti.activity(); f(); } });
414	  onClick('bkSigL', () => bkSignal(state!, 1));
415	  onClick('bkSigR', () => bkSignal(state!, -1));
416	  onClick('bkView', () => bike.setView(camB.view === 3 ? 1 : 3));
417	  onClick('bkReset', () => bkRecover(state!, net!));
418	  if (hornBtn) {
419	    let hornId = -1;
420	    hornBtn.addEventListener('pointerdown', (e) => {
421	      if (!active() || hornId !== -1) return;
422	      e.preventDefault();
423	      hornId = e.pointerId; hornTouch = true; hornBtn.classList.add('on'); exMulti.activity();
424	      try { hornBtn.setPointerCapture(e.pointerId); } catch { /* con trỏ không còn hoạt động */ }
425	    });
426	    const hornEnd = (e: PointerEvent) => { if (e.pointerId === hornId) { hornId = -1; hornOff(); } };
427	    hornBtn.addEventListener('pointerup', hornEnd);
428	    hornBtn.addEventListener('pointercancel', hornEnd);
429	    hornBtn.addEventListener('lostpointercapture', hornEnd);
430	    hornBtn.addEventListener('contextmenu', (e) => e.preventDefault());
431	  }
432	  /* Cảm ứng: drive/touch.ts trên cùng #drHud (bộ của ô tô cũng gắn ở đó nhưng chỉ đọc khi đang lái ô tô); vuốt #drLook nhìn quanh */
433	  const hud = d('drHud');
434	  if (hud) touch = drTouchBind(hud, { look: (dx, dy) => { if (active()) bkCamDrag(camB, dx, dy); }, activity: () => exMulti.activity() });
435	  const touchUi = () => typeof matchMedia === 'function' && matchMedia('(hover: none)').matches;
436	  bkSound.bind(document.getElementById('drSoundBtn'));   // nút 🔊 / 🔇 chung với ô tô: chỉ toggle tiếng xe máy khi đang lái xe máy
437	  /* Kéo chuột trái / vuốt (một ngón) trên canvas: nhìn quanh (góc thứ nhất) hoặc quay quanh xe (góc thứ ba) */
438	  let dragId = -1, lx = 0, ly = 0;
439	  canvas.addEventListener('pointerdown', (e) => {
440	    if (!active() || e.button !== 0 || dragId !== -1) return;
441	    if (e.pointerType === 'touch' && touchUi()) return;   // có giao diện cảm ứng: ngón tay vuốt #drLook (touch.ts), không giành con trỏ ở đây
442	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
443	    canvas.setPointerCapture(e.pointerId);
444	  });
445	  canvas.addEventListener('pointermove', (e) => {
446	    if (e.pointerId !== dragId) return;
447	    bkCamDrag(camB, e.clientX - lx, e.clientY - ly);
448	    lx = e.clientX; ly = e.clientY;
449	  });
450	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
451	  canvas.addEventListener('pointerup', end);
452	  canvas.addEventListener('pointercancel', end);
453	  canvas.addEventListener('lostpointercapture', end);
454	}
