/* ?test&perf: bật đo thời gian CPU từng bước trong vòng animate (tests/perf-check.mjs) */
const query = new URLSearchParams(location.search);
/* Cho test nhiều người (Task 5; sảnh thật là Task 6): mở phiên, vào phòng bằng tên, bay khi được cấp slot */
const multiTest = {
  url: () => exMulti.url(), get session() { return exMulti.session; }, remotes: exRemotes,
  fly(name: string): boolean {
    return exMulti.begin(() => {
      exMulti.onChange = () => { if (exMulti.session!.phase === 'flying' && !explore.active()) explore.start(); };
      exMulti.session!.join(name);
    });
  }
};
if (query.has('test')) {
  perf.on = query.has('perf');
  (window as unknown as { __app: unknown }).__app = { reflectState, renderer, scene, camera, controls, cam, shared, songHan, hr: hanTunnel, sunWheel, riverfront, weather, hrDrive, swRide, windFx, THREE: TEST_THREE, dayNight, lights: lightState, tours: TOURS, tour, narration, audio, perf, quality, ui: { ...ui, ui: compactState, openSheet, closeSheets, reveal }, explore, keys, multi: multiTest, exFlight: { exCreate, exStep, exInputFromKeys, exBuildGlider, exPlaceGlider, exChase, CONFIG_explore: CONFIG.explore }, boats: boatsTest, traffic: trafficTest, trees: treesTest, people: peopleTest,
    stroll: { stroll, stValid, stGroundY, stMove, stCamPlace, CONFIG_stroll: CONFIG.stroll, avatars: stAvatars }, drive, bike };
}

/* ============================ Vòng lặp ============================ */
const clock = new THREE.Clock();
const fpsEl = document.getElementById('fps'), callsEl = document.getElementById('calls'), showEl = document.getElementById('showState'), ftimeEl = document.getElementById('ftime');

const CAR = CONFIG.drive.car, SIM = CONFIG.drive.sim;
export const DR_CAR_BODY: DrBody = { hl: CAR.length / 2, hw: CAR.width / 2, ax: CAR.wheelbase / 2, height: CAR.height };   // VF 3 (hành vi cũ)
let HL = 0, HW = 0;                                                  // nửa dài, nửa rộng thân xe đang dùng, m
let AX = 0;                                                          // tâm → trục sau, m
let REACH = 0;                                                       // trục sau → góc xe xa nhất: quãng góc xe quét khi xoay dyaw là ≤ REACH · |dyaw|
let HT = 0;                                                          // chiều cao thân xe (kể cả người lái), m
/* Đặt thân xe đang dùng cho mọi hàm của module (ô tô hoặc xe máy); người gọi đặt trước khi mô phỏng, không đổi giữa chừng một drMove */
export function drUseBody(b: DrBody): void {
  HL = b.hl; HW = b.hw; AX = b.ax; HT = b.height;
  REACH = AX + Math.hypot(HL, HW);
}
drUseBody(DR_CAR_BODY);
const EPS = 1e-9;

/* ===== Chỉ mục lưới vật cản ===== */
const DRC = 16;          // cạnh ô lưới, m
const DR_BIG = 64;       // vật cản phủ hơn số ô này thì vào danh sách "lớn"
import { drGround, type DrNet } from '../drive/net';
import type { BkState } from './motion';

const FB = CONFIG.bike.fx.beam, FS = CONFIG.bike.fx.spray, FG = CONFIG.bike.fx.gust, P = CONFIG.bike.perf, L = CONFIG.bike.body.wheelbase, LOCK = CONFIG.bike.model.steerLock;
const fin = (v: number, d = 0): number => (Number.isFinite(v) ? v : d);
const clamp01 = (v: number): number => (v < 0 ? 0 : v > 1 ? 1 : v);

/* ===== Hàm thuần ===== */
export function bkGrip(wet: number, inTunnel: boolean): number {
  if (inTunnel) return 1;
  return 1 - clamp01(fin(wet));
}

export function bkGustSteer(v: number, gust: number, wdx: number, wdz: number, yaw: number): number {
  if (!(fin(v) > P.vBlend)) return 0;
  const g = clamp01(fin(gust) / FG.ref);
  if (g === 0) return 0;
  /* bên trái thân xe: (−sin yaw, −cos yaw) (mũi (cos yaw, −sin yaw), trục Y lên) */
  const side = -fin(wdx) * Math.sin(yaw) - fin(wdz) * Math.cos(yaw);
  return FG.steer * g * (side > 1 ? 1 : side < -1 ? -1 : side);
}

/* ===== Vệt đèn pha ===== */
const ROWS = FB.rows, NB = 2 * (ROWS + 1);

/* Texture quạt: u ngang (0..1), v dọc (0 gần xe .. 1 xa); độ sáng ghi vào RGB (cộng màu nhân alpha = 1), hẹp ở gần, mở theo căn bậc hai, tắt dần ở xa, đốm sáng ở ≈ 0,3 */
function beamTexture(): THREE.DataTexture {
  const n = FB.px, d = new Uint8Array(n * n * 4);
  let mx = 0;
  const f = new Float32Array(n * n);
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const u = (x + 0.5) / n, v = (y + 0.5) / n;
    const half = 0.22 + 0.78 * Math.sqrt(v), e = Math.abs(u - 0.5) * 2 / half, across = e >= 1 ? 0 : 1 - e * e;   // quạt mở nhanh ở gần xe
    const rise = Math.min(1, v / 0.06), along = rise * rise * (3 - 2 * rise) * Math.pow(1 - v, 1.1) * (0.7 + 0.3 * Math.exp(-(((v - 0.3) / 0.2) ** 2)));
    f[y * n + x] = across * along; mx = Math.max(mx, across * along);
  }
  for (let i = 0; i < n * n; i++) { const c = Math.round(255 * f[i] / mx); d[i * 4] = c; d[i * 4 + 1] = c; d[i * 4 + 2] = c; d[i * 4 + 3] = 255; }
  const t = new THREE.DataTexture(d, n, n, THREE.RGBAFormat);
  t.magFilter = THREE.LinearFilter; t.minFilter = THREE.LinearFilter; t.needsUpdate = true;
  return t;
}

