      check(`8 quãng phanh 50 km/h → 0: khô ${br[1].toFixed(2)} m, ướt ${br[0].toFixed(2)} m (dài hơn ${((br[0] / br[1] - 1) * 100).toFixed(1)} %, ≥ 20 %)`, br[0] >= 1.2 * br[1]);
      const sp = await P.evaluate(() => {
        const B = window.__app.bike; window.__bk.hideTraffic();
